"""Move actual editor windows into documents without reconstructing their domain views."""
from playwright.sync_api import expect

def verify_window_documents(page,project,mount,send,envelope,settle,restart):
 page.set_viewport_size({'width':1440,'height':1000});before={p:p.read_bytes() for p in project.iterdir() if p.is_file()}
 def ready():expect(page.locator('#nav')).to_be_enabled(timeout=180000)
 def state():
  v=mount();s=v['state'];assert send(envelope(v,'dispose'))['ok'];return s
 def saved():page.evaluate('()=>globalThis.confectoryFlushPresentation()');return state()['presentation']
 def window(key):return page.locator('.window[data-key="'+key+'"]')
 def tab(key):return page.locator('[data-window-tab="'+key+'"]')
 def home():page.locator('#workspace-home-tab').click()
 def context_dock(key):
  window(key).locator('.window-title').click(button='right',position={'x':110,'y':18});page.locator('.context-menu').get_by_role('button',name='탭으로 열기',exact=True).click();expect(window(key)).to_have_class('window window-document tab-document')
 def blank():
  area=page.locator('#workspace').bounding_box()
  for fx in [.86,.62,.35,.12]:
   for fy in [.68,.43,.23]:
    p={'x':area['x']+area['width']*fx,'y':area['y']+area['height']*fy}
    if page.evaluate("p=>{const el=document.elementFromPoint(p.x,p.y);return el?.id==='workspace'||(el?.closest('#workspace')&&!el.closest('.window,.workspace-decoration,.bubble-dock,.workspace-tabs,.tab-document'))}",p):return {'x':area['width']*fx,'y':area['height']*fy}
  raise AssertionError('no blank Workspace point')
