 source.press('Control+End');source.press('End');source.press('x');expect(source).to_have_value(pending+'x');source.press('Control+z');expect(source).to_have_value(pending);source.press('Control+Shift+z');expect(source).to_have_value(pending+'x');pending+='x';window('source').focus();page.keyboard.press('Delete');expect(source).to_have_value(pending)
 camera=saved()['workspaceView'];heading=window('source').locator('.window-title').bounding_box();page.mouse.move(heading['x']+120,heading['y']+18);page.mouse.wheel(0,600);page.mouse.down(button='middle');page.mouse.move(heading['x']+200,heading['y']+32,steps=6);page.mouse.up(button='middle');assert saved()['workspaceView']==camera,'document wheel/middle drag must not pan or zoom the hidden Workspace'
 # A second actual window uses title drag to the tabs; the original input stays alive.
 home();expect(source).not_to_be_visible();box=window('browser').locator('.window-title').bounding_box();tabs=page.locator('#workspace-tabs').bounding_box();page.mouse.move(box['x']+110,box['y']+18);page.mouse.down();page.mouse.move(tabs['x']+tabs['width']-100,tabs['y']+18,steps=15);page.mouse.up();expect(tab('browser')).to_be_visible();expect(window('browser')).not_to_be_visible();tab('browser').click();expect(window('browser')).to_be_visible();tab('source').click();expect(source).to_have_value(pending);assert source.evaluate('el=>el===globalThis.__windowDocumentSource')
 # Global documents survive canvas navigation, and close returns a hidden retained source to its original owner.
 home();page.locator('#workspace').click(button='right',position=blank());page.get_by_role('button',name='하위 Workspace 만들기',exact=True).click();page.locator('.workspace-portal').last.dblclick();tab('source').click();expect(source).to_have_value(pending);page.locator('[data-window-tab-close="source"]').click();expect(tab('source')).to_have_count(0);p=saved();assert next(row for row in p['layout'] if row['key']=='source')['hidden'];home();tab('browser').click();page.locator('#browser-actions').click();page.locator('#advanced-source').click();expect(source).to_have_value(pending);assert source.evaluate('el=>el===globalThis.__windowDocumentSource');context_dock('source')
 # Notes and actual window documents are mutually exclusive views of the same project.
 home();page.locator('#workspace').click(button='right',position=blank());page.get_by_role('button',name='메모 만들기',exact=True).click();note=page.locator('.workspace-note').last;note.locator('textarea').fill('Independent private note');note.locator('.workspace-item-name').dblclick();expect(page.locator('.workspace-note-document')).to_be_visible();expect(source).not_to_be_visible();tab('source').click();expect(source).to_be_visible();expect(page.locator('.workspace-note-document')).not_to_be_visible();page.screenshot(path='/tmp/confectory-v480-window-document.png',full_page=True);saved()
 restart();ready();expect(source).to_be_visible(timeout=60000);expect(source).to_have_value(pending);expect(tab('source')).to_have_attribute('aria-selected','true');expect(page.locator('#apply')).to_be_enabled();expect(page.locator('.window[data-key="source"]')).to_have_count(1)
 page.locator('.brand').click();page.locator('#home-projects').wait_for();page.locator('[data-enter]').click();ready();expect(source).to_be_visible();expect(source).to_have_value(pending)
 window('source').locator('[data-document-return]').click();expect(tab('source')).to_have_count(0);expect(source).to_be_visible();assert saved()['activeWorkspaceId']=='root';context_dock('source');expect(source).to_have_value(pending);page.screenshot(path='/tmp/confectory-v480-window-document-cold.png',full_page=True)
 tab('editor-1').click();expect(prop.locator('[data-description]')).to_have_value('DOC_PROPERTY_PENDING');assert [(row['view'],row['id'],row['mode']) for row in state()['editorViews']]==bindings;tab('source').click();page.locator('[data-window-tab-close="editor-1"]').click();expect(tab('editor-1')).to_have_count(0);expect(prop.locator('[data-description]')).to_have_value('DOC_PROPERTY_PENDING');assert [(row['view'],row['id'],row['mode']) for row in state()['editorViews']]==bindings;expect(source).to_be_visible()
 # The docked source uses the ordinary explicit Save/Review/compiler Confirm path.
 page.locator('#save').click();expect(page.locator('#status')).to_have_text('Draft saved; final sources unchanged',timeout=60000);assert all(p.read_bytes()==value for p,value in before.items());tab('source').click();page.locator('#review').click();review=window('review');expect(review.locator('[data-review-advanced]')).to_be_visible(timeout=180000);review.locator('[data-review-advanced]').click();review.locator('[data-advanced-reviewed]').check();expect(page.locator('#confirm')).to_be_enabled();page.locator('#confirm').click();expect(page.locator('#status')).to_have_text('Source confirmed',timeout=180000);assert (project/'Score.celem').read_text()==pending;assert all(p.read_bytes()==value for p,value in before.items() if p.name!='Score.celem')
 print('PASS actual v480 window documents: exact source DOM and native input undo/redo retained, context and title drag docking, global child navigation and hidden close ownership, note/window mutual exclusion, true cold and Home active source plus independent property pending input and unchanged domain View slot on document close, explicit Workspace return and ordinary Save/Review/compiler Confirm with other original files preserved',flush=True)
